# Go/No-Go Decision Scorecard (Python)
import pandas as pd

def calculate_deployment_score(criteria):
    """Risk-adjusted scoring for AI deployment decisions"""
    weights = {
        'technical_readiness': 0.25,
        'business_value': 0.20,
        'risk_profile': 0.30,  # Higher weight on risk
        'ethical_alignment': 0.15,
        'operational_feasibility': 0.10
    }

    score = sum(criteria[k] * weights[k] for k in weights)

    # Veto conditions
    if criteria['risk_profile'] < 5.0:  # Scale 1-10
        return {'decision': 'NO-GO', 'score': score, 
                'reason': 'Risk profile below threshold'}
    if criteria['ethical_alignment'] < 6.0:
        return {'decision': 'NO-GO', 'score': score,
                'reason': 'Ethical concerns unresolved'}

    decision = 'GO' if score >= 7.0 else 'CONDITIONAL'
    return {'decision': decision, 'score': round(score, 2)}

# Example usage
project_criteria = {
    'technical_readiness': 8.5,
    'business_value': 9.0,
    'risk_profile': 6.5,
    'ethical_alignment': 7.0,
    'operational_feasibility': 7.5
}

result = calculate_deployment_score(project_criteria)
print(f"Decision: {result['decision']}, Score: {result['score']}")
